mapper.select:
SELECT * FROM ( SELECT V.VERIFICATION_NO, V.MEMBER_NO, V.VERIFICATION_FILE, V.ORIGINAL_NAME, V.RENAMED_NAME, V.STATUS, V.ADMIN_COMMENT, TO_CHAR(V.SUBMITTED_AT, 'YYYY-MM-DD HH24:MI') AS SUBMITTED_AT, TO_CHAR(V.PROCESSED_AT, 'YYYY-MM-DD HH24:MI') AS PROCESSED_AT, V.PROCESSED_BY, M.NICKNAME, M.EMAIL, M.PROFILE_IMAGE, ROW_NUMBER() OVER (ORDER BY V.SUBMITTED_AT DESC) AS RN FROM MEMBER_VERIFICATION V JOIN MEMBER M ON V.MEMBER_NO = M.MEMBER_NO WHERE 1=1
AND V.STATUS = #{status}
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE MEMBER_VERIFICATION
SET STATUS = #{status},
    ADMIN_COMMENT = #{adminComment},
    PROCESSED_AT = SYSDATE,
    PROCESSED_BY = #{processedBy}
WHERE VERIFICATION_NO = #{verificationNo}
